/*
 * A397954  Polydivisible numbers in base 4.
 * https://oeis.org/A397954
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy, fini, full
 * Formula:   a(n) is the n-th smallest polydivisible number in base 4. The
 *            sequence is generated by breadth‑first search: starting from
 *            1‑digit numbers 1,2,3 (and 0 as a special case), each step
 *            appends a base‑4 digit d∈{0,1,2,3} to produce a longer number.
 *            The new number is accepted only if its decimal value...
 * Range:     u8 n <= 26, u16 n <= 38, u32 n <= 38, u64 n <= 38, u128 n <= 38,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

static seq_t *values = NULL;          /* cached values */
static idx_t *lengths = NULL;          /* cached digit lengths */
static size_t cap = 0;                 /* capacity of the arrays */
static size_t len = 0;                 /* number of stored values */
static size_t frontier_start = 0;      /* start index of current frontier */
static size_t frontier_end = 0;        /* end index (exclusive) of frontier */

/* Ensure arrays have at least 'need' additional slots. */
static void ensure_capacity(size_t need)
{
    if (len + need > cap) {
        size_t newcap = cap ? cap * 2 : 16;
        while (len + need > newcap)
            newcap *= 2;
        values  = (seq_t *)realloc(values,  newcap * sizeof(seq_t));
        lengths = (idx_t *)realloc(lengths, newcap * sizeof(idx_t));
        cap = newcap;
    }
}

/* Generate polydivisible numbers until we have at least 'needed' terms. */
static void grow_sequence(idx_t needed)
{
    if (len == 0) {
        /* Initial seed: 0,1,2,3.  0 is special – we do not extend it. */
        ensure_capacity(4);
        values[0] = 0;          lengths[0] = 1;
        values[1] = 1;          lengths[1] = 1;
        values[2] = 2;          lengths[2] = 1;
        values[3] = 3;          lengths[3] = 1;
        len = 4;
        frontier_start = 1;     /* start with numbers 1,2,3 */
        frontier_end   = 4;
    }

    while (len < needed) {
        size_t start = frontier_start;
        size_t end   = frontier_end;

        /* The next frontier starts where the current one ends. */
        frontier_start = end;
        /* We may obtain at most 4×(end‑start) new numbers. */
        ensure_capacity( 4 * (end - start) );

        for (size_t i = start; i < end; ++i) {
            seq_t  old_val = values[i];
            idx_t  old_len = lengths[i];
            if (old_val == 0) continue;          /* avoid leading‑zero repeats */

            idx_t new_len = old_len + 1;
            for (int d = 0; d < 4; ++d) {
                seq_t new_val = old_val * 4 + (seq_t)d;
                if (new_val % (seq_t)new_len == 0) {
                    values[len]  = new_val;
                    lengths[len] = new_len;
                    ++len;
                }
            }
        }
        frontier_end = len;                      /* new frontier ends here */
        /* If the frontier becomes empty before reaching the target,
           the sequence is finite (unlikely for base 4). */
        if (frontier_start >= frontier_end) break;
    }
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;                      /* only used for safety   */
    grow_sequence(n);
    return values[n - 1];
}
